args.sql:
SELECT p.pat_key, 
       COALESCE((SELECT CAST(SPLIT_PART(ab.hosp_risk_density, ' ', 1) AS numeric) FROM assessmentbasics ab WHERE ab.pat_owner_ref = p.pat_key ORDER BY ab.ab_key DESC LIMIT 1), 0) as latest_hosp_risk,
       CASE WHEN EXISTS(SELECT 1 FROM assessmentbasics ab WHERE ab.pat_owner_ref = p.pat_key AND CAST(SPLIT_PART(ab.hosp_risk_density, ' ', 1) AS numeric) > 1.5 ORDER BY ab.ab_key DESC LIMIT 1) THEN TRUE ELSE FALSE END as needs_case_review FROM patients p;
